  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "EM574, a macrolide structurally similar to the query, has an estimated oral bioavailability of only 2% in humans based on mean oral clearance (CL/F 4500 L/h) versus hepatic blood flow (90 L/h), indicating very low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "The oral bioavailability of EM574 in humans is approximately 0.02, directly supporting a low-F outcome for a closely related macrolide scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "EM574 shows very low oral bioavailability in humans, with mean oral clearance about 50-fold higher than hepatic blood flow, reinforcing the low-F analogy for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "9-Nitrocamptothecin, a complex lipophilic lactone, has very low absolute oral bioavailability in humans, supporting low F for similarly complex, poorly water-soluble polycyclic lactones.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Tigecycline, a large complex natural-product-like molecule, is only administered IV due to low oral bioavailability, providing a moderate-transferability low-F signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly oxygenated polycyclic macrolide-like ester. The most transferable evidence, from the structurally similar macrolide EM574, consistently shows very low oral bioavailability (~2%) in humans. Additional complex lipophilic lactones (9-NC, tigecycline) also show low F. Although some records involve structurally distant molecules, the affirmative low-F evidence from macrolide-like scaffolds outweighs the limited high-F evidence from omadacycline, which is structurally dissimilar. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "The most transferable evidence (EM574) is based on indirect clearance estimates rather than direct IV-oral comparisons.",
    "Structural differences between the query and EM574 (e.g., tert-butyl group, additional oxygen bridges) may alter absorption and metabolism."
  ],
  "new_evidence_assessment": [
